'use client'

import React, { useCallback, type FC, type ReactNode } from 'react'
import cssStyles from './Pagination.module.css'
import { emitDiag } from '../../utils/diag'
import FirstPageIcon from '../Icons/FirstPage'
import LastPageIcon from '../Icons/LastPage'
import KeyboardArrowLeftIcon from '../Icons/KeyboardArrowLeft'
import KeyboardArrowRightIcon from '../Icons/KeyboardArrowRight'

function mergeClassNames(...names: Array<string | undefined>): string {
  return names.filter(Boolean).join(' ')
}

export interface PaginationProps {
  page: number
  count: number
  onChange: (event: React.MouseEvent<HTMLButtonElement>, page: number) => void
  siblingCount?: number
  boundaryCount?: number
  hidePrevButton?: boolean
  hideNextButton?: boolean
  showFirstButton?: boolean
  showLastButton?: boolean
  /**
   * Stable test selector — emitted as `data-pagination-field` on the
   * <nav> root. Use when the page has multiple pagination instances (e.g.
   * a contracts grid + a categories grid on the same workspace tab) so
   * tests / the harvest can locate the right one without relying on
   * positional traversal.
   */
  dataField?: string
  /**
   * ARIA label for the navigation landmark. Defaults to "pagination navigation".
   * Override per-instance when several paginations live on the same page so
   * screen reader users can disambiguate.
   */
  ariaLabel?: string
  styles?: {
    /** Disables every page/nav button. */
    disabled?: boolean
    /** 'sacred' renders the gold palette; anything else keeps the default. */
    theme?: string
    /** Gap between the button container's children (CSS length). */
    gap?: string
    /** Padding on the root nav (CSS length; default 8px). */
    padding?: string
  }
  renderItem?: (item: PaginationRenderItemParams) => ReactNode
  /**
   * Forwarded ref to the root `<nav>` navigation landmark (React 19
   * ref-as-prop). Pagination renders a LIST of page/nav `<button>`s, so there is
   * no single "the button" — the landmark is the meaningful consumer handle
   * (scroll the pager into view, measure it, or query its buttons). Individual
   * buttons remain reachable via their `data-action`/`aria-label` selectors.
   */
  ref?: React.Ref<HTMLElement>
}

export interface PaginationRenderItemParams {
  page: number | null
  type:
    | 'page'
    | 'first'
    | 'last'
    | 'next'
    | 'previous'
    | 'start-ellipsis'
    | 'end-ellipsis'
  selected: boolean
  disabled: boolean
  onClick: (event: React.MouseEvent<HTMLButtonElement>) => void
}

const range = (start: number, end: number): number[] => {
  const length = end - start + 1
  return Array.from({ length }, (_, i) => start + i)
}

const usePagination = ({
  count,
  page,
  siblingCount = 1,
  boundaryCount = 1,
}: {
  count: number
  page: number
  siblingCount?: number
  boundaryCount?: number
}) => {
  const startPages = range(1, Math.min(boundaryCount, count))
  const endPages = range(
    Math.max(count - boundaryCount + 1, boundaryCount + 1),
    count
  )

  const siblingsStart = Math.max(
    Math.min(page - siblingCount, count - boundaryCount - siblingCount * 2 - 1),
    boundaryCount + 2
  )
  const firstEndPage = endPages.length > 0 ? endPages[0] : undefined
  const siblingsEnd = Math.min(
    Math.max(page + siblingCount, boundaryCount + siblingCount * 2 + 2),
    firstEndPage !== undefined ? firstEndPage - 2 : count - 1
  )

  const itemList: (number | 'start-ellipsis' | 'end-ellipsis')[] = [
    ...startPages,
    ...(siblingsStart > boundaryCount + 2
      ? ['start-ellipsis' as const]
      : boundaryCount + 1 < count - boundaryCount
        ? [boundaryCount + 1]
        : []),
    ...range(siblingsStart, siblingsEnd),
    ...(siblingsEnd < count - boundaryCount - 1
      ? ['end-ellipsis' as const]
      : count - boundaryCount > boundaryCount
        ? [count - boundaryCount]
        : []),
    ...endPages,
  ]

  return itemList
}

const PaginationButton: FC<{
  onClick: (event: React.MouseEvent<HTMLButtonElement>) => void
  disabled: boolean
  children: ReactNode
  'aria-label'?: string
  /** Canonical action verb emitted as `data-action` (first/prev/next/last). */
  action: string
}> = ({ onClick, disabled, children, 'aria-label': ariaLabel, action }) => {
  // A boundary-/globally-disabled direction button stays FOCUSABLE via
  // `aria-disabled` rather than the native `disabled` attribute. Native
  // `disabled` drops the element from the focus order, so a keyboard user who
  // presses Enter on "Next"/"Last" to reach the final page (or "Prev"/"First"
  // to reach page 1) has focus fall to <body> the instant the just-activated
  // control disables on the re-render — the disabled-focused-element
  // anti-pattern (WCAG 2.4.3 Focus Order). aria-disabled keeps focus ON the
  // control (still exposing the unavailable state to assistive tech) while the
  // handler is neutralised so an aria-disabled button never navigates — it can
  // never step past a boundary to page 0 / count+1. Matches the library's
  // aria-disabled contract: emit "true" when disabled, OMIT it when enabled
  // (never "false").
  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled) {
      event.preventDefault()
      return
    }
    onClick(event)
  }

  return (
    <button
      onClick={handleClick}
      aria-disabled={disabled || undefined}
      aria-label={ariaLabel}
      data-action={action}
      className={mergeClassNames(cssStyles.button, cssStyles.navButton)}
    >
      {children}
    </button>
  )
}

const PaginationItem: FC<{
  item: number | 'start-ellipsis' | 'end-ellipsis'
  page: number
  count: number
  onChange: (event: React.MouseEvent<HTMLButtonElement>, page: number) => void
  renderItem?: (item: PaginationRenderItemParams) => ReactNode
}> = ({ item, page, onChange, renderItem }) => {
  if (item === 'start-ellipsis' || item === 'end-ellipsis') {
    const ellipsisItem: PaginationRenderItemParams = {
      page: null,
      type: item,
      selected: false,
      disabled: true,
      onClick: () => {},
    }

    if (renderItem) {
      return <>{renderItem(ellipsisItem)}</>
    }

    return <div className={cssStyles.ellipsis}>…</div>
  }

  const isSelected = item === page
  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    onChange(event, item)
  }

  const renderItemParams: PaginationRenderItemParams = {
    page: item,
    type: 'page',
    selected: isSelected,
    disabled: false,
    onClick: handleClick,
  }

  if (renderItem) {
    return <>{renderItem(renderItemParams)}</>
  }

  return (
    <button
      onClick={handleClick}
      className={mergeClassNames(cssStyles.button, cssStyles.pageButton)}
      aria-current={isSelected ? 'page' : undefined}
      // Differentiate the accessible name once a page is active: the current
      // page reads "page N" (it already carries aria-current="page", so the
      // "Go to" call-to-action verb would be a mild contradiction — "Go to
      // page 5, current page"), while every other page keeps the "Go to page N"
      // action name (mirrors the MUI reference pattern). WCAG 2.5.3 Label in
      // Name still holds either way — the visible "N" is contained in both.
      aria-label={isSelected ? `page ${item}` : `Go to page ${item}`}
      data-action="goto-page"
      data-pagination-page={item}
      data-pagination-selected={isSelected ? 'true' : 'false'}
    >
      {item}
    </button>
  )
}

const Pagination: FC<PaginationProps> = ({
  page,
  count,
  onChange,
  siblingCount = 1,
  boundaryCount = 1,
  hidePrevButton = false,
  hideNextButton = false,
  showFirstButton = false,
  showLastButton = false,
  dataField,
  ariaLabel,
  styles,
  renderItem,
  ref,
  ...rest
}) => {
  const isDisabled = styles?.disabled
  // Preserve the pre-migration default: only an explicit `theme: 'sacred'`
  // rendered the gold palette (old `isSacredTheme = styles?.theme === 'sacred'`).
  // Every other value — including no theme at all — rendered the MUI palette,
  // which is the bare `.root` default in Pagination.module.css and
  // `[data-theme='sacred']` carries the gold. Emitting the raw theme (no
  // sacred fallback) keeps a no-theme callsite on the MUI palette so the
  // rendered output matches HEAD exactly.
  const theme = styles?.theme

  const items = usePagination({
    count,
    page,
    siblingCount,
    boundaryCount,
  })

  // Additive diagnostics: emit a single nav.change for every page change
  // (nav buttons AND numbered page items route through this), then fire the
  // caller's own onChange. emitDiag is a no-op without a host bus.
  const handleChange = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>, nextPage: number) => {
      emitDiag({
        type: 'nav.change',
        component: 'Pagination',
        to: String(nextPage),
      })
      onChange(event, nextPage)
    },
    [onChange]
  )

  const handleFirstPage = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (!isDisabled) {
        handleChange(event, 1)
      }
    },
    [handleChange, isDisabled]
  )

  const handlePreviousPage = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (!isDisabled) {
        handleChange(event, page - 1)
      }
    },
    [handleChange, page, isDisabled]
  )

  const handleNextPage = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (!isDisabled) {
        handleChange(event, page + 1)
      }
    },
    [handleChange, page, isDisabled]
  )

  const handleLastPage = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (!isDisabled) {
        handleChange(event, count)
      }
    },
    [handleChange, count, isDisabled]
  )

  if (count <= 1) {
    return null
  }

  return (
    <nav
      ref={ref}
      className={cssStyles.root}
      data-component="Pagination"
      data-theme={theme}
      role="navigation"
      aria-label={ariaLabel ?? 'pagination navigation'}
      data-pagination-root="true"
      data-pagination-current-page={page}
      data-pagination-count={count}
      {...(dataField !== undefined && { 'data-pagination-field': dataField })}
      style={
        {
          ...(styles?.gap !== undefined && { '--pagination-gap': styles.gap }),
          ...(styles?.padding !== undefined && {
            '--pagination-padding': styles.padding,
          }),
        } as React.CSSProperties
      }
      {...rest}
    >
      {/*
        Screen-reader-only status (WCAG 4.1.3 Status Messages). Selecting a page
        flips `aria-current` on a page button, but that attribute change is NOT
        reliably announced when focus stays on the just-clicked control — so a
        polite, atomic live region states the real active page after every
        change. A live region never announces its initial value, so this speaks
        only on a user-driven page change, not on first render.
      */}
      <div
        className={cssStyles.visuallyHidden}
        role="status"
        aria-live="polite"
        aria-atomic="true"
      >
        Page {page} of {count}
      </div>
      {/*
        Pagination is a list of navigation controls, so the items render as a
        real <ul>/<li> list inside the <nav> landmark (mirrors the Breadcrumb
        landmark). Screen readers announce the item count and let users step
        through the pages; the flat <div> gave no such structure (WCAG 1.3.1).
        The direction icons are decorative — the wrapping <button> already
        carries the accessible name via aria-label — so each is aria-hidden to
        avoid redundant / noisy SVG announcements (WCAG 1.1.1 / 4.1.2).
      */}
      <ul className={cssStyles.buttonContainer}>
        {showFirstButton && (
          <li className={cssStyles.listItem}>
            <PaginationButton
              onClick={handleFirstPage}
              disabled={page <= 1 || !!isDisabled}
              aria-label="Go to first page"
              action="first"
            >
              <FirstPageIcon
                aria-hidden="true"
                styles={
                  styles?.theme
                    ? { theme: styles.theme as 'sacred' | 'dark' | 'light' }
                    : {}
                }
              />
            </PaginationButton>
          </li>
        )}

        {!hidePrevButton && (
          <li className={cssStyles.listItem}>
            <PaginationButton
              onClick={handlePreviousPage}
              disabled={page <= 1 || !!isDisabled}
              aria-label="Go to previous page"
              action="prev"
            >
              <KeyboardArrowLeftIcon
                aria-hidden="true"
                styles={
                  styles?.theme
                    ? { theme: styles.theme as 'sacred' | 'dark' | 'light' }
                    : {}
                }
              />
            </PaginationButton>
          </li>
        )}

        {/*
          Key on the item's CONTENT (page number, or the unique start/end
          ellipsis token), NOT the array index. As the visible window shifts
          the same DOM <button> is then reused for the same page, so keyboard/AT
          focus stays on the page the user just activated (which becomes the
          current page) instead of drifting to whatever number now occupies that
          array slot (WCAG 2.4.3 Focus Order). Both ellipses are unique per
          render, so keys never collide.
        */}
        {items.map((item) => (
          <li
            key={typeof item === 'number' ? `page-${item}` : item}
            className={cssStyles.listItem}
          >
            <PaginationItem
              item={item}
              page={page}
              count={count}
              onChange={handleChange}
              {...(renderItem ? { renderItem } : {})}
            />
          </li>
        ))}

        {!hideNextButton && (
          <li className={cssStyles.listItem}>
            <PaginationButton
              onClick={handleNextPage}
              disabled={page >= count || !!isDisabled}
              aria-label="Go to next page"
              action="next"
            >
              <KeyboardArrowRightIcon
                aria-hidden="true"
                styles={
                  styles?.theme
                    ? { theme: styles.theme as 'sacred' | 'dark' | 'light' }
                    : {}
                }
              />
            </PaginationButton>
          </li>
        )}

        {showLastButton && (
          <li className={cssStyles.listItem}>
            <PaginationButton
              onClick={handleLastPage}
              disabled={page >= count || !!isDisabled}
              aria-label="Go to last page"
              action="last"
            >
              <LastPageIcon
                aria-hidden="true"
                styles={
                  styles?.theme
                    ? { theme: styles.theme as 'sacred' | 'dark' | 'light' }
                    : {}
                }
              />
            </PaginationButton>
          </li>
        )}
      </ul>
    </nav>
  )
}

Pagination.displayName = 'Pagination'
export default Pagination
